const H = (personalization: string, ...parts: Uint8Array[]) => blake2b(concatBytes(...parts), { dkLen: 32, personalization: utf8ToBytes(personalization) });

/**
 * A ZIP-225 v5 transaction read field by field, with its Sapling and Orchard digests computed per
 * ZIP-244 § T.3 and T.4 — independent of the encoder and digests under test.
 */
function parseV5(bytes: Uint8Array) {
  let i = 0;
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const take = (n: number) => {
    if (i + n > bytes.length) throw new Error('truncated');
    const out = bytes.slice(i, i + n);
    i += n;
    return out;
  };
  const u32 = () => {
    const v = dv.getUint32(i, true);
    i += 4;
    return v;
  };
  const i64 = () => {
    const v = dv.getBigInt64(i, true);
    i += 8;
    return v;
  };
  const size = () => {
    const x = take(1)[0];
    if (x < 0xfd) return x;
    if (x === 0xfd) return take(2).reduce((acc, b, k) => acc + b * 256 ** k, 0);
    if (x === 0xfe) return u32();
    throw new Error('size');
  };
  const header = u32();
  const versionGroupId = u32();
  const branchId = u32();
  const lockTime = u32();
  const expiryHeight = u32();
  const inputs = Array.from({ length: size() }, () => ({ txid: take(32), index: u32(), scriptSig: take(size()), sequence: u32() }));
  const outputs = Array.from({ length: size() }, () => ({ value: i64(), script: take(size()) }));
  const transparentEnd = i;

  const spends = Array.from({ length: size() }, () => ({ cv: take(32), nf: take(32), rk: take(32) }));
  const sOuts = Array.from({ length: size() }, () => ({ cv: take(32), cmu: take(32), epk: take(32), enc: take(580), out: take(80) }));
  let sapling = H('ZTxIdSaplingHash');
  if (spends.length + sOuts.length > 0) {
    const valueBalance = take(8);
    const anchor = spends.length > 0 ? take(32) : new Uint8Array(0);
    take(192 * spends.length + 64 * spends.length + 192 * sOuts.length + 64); // proofs, spend auth sigs, binding sig
    const spendsDigest = spends.length
      ? H('ZTxIdSSpendsHash', H('ZTxIdSSpendCHash', ...spends.map((s) => s.nf)), H('ZTxIdSSpendNHash', ...spends.flatMap((s) => [s.cv, anchor, s.rk])))
      : H('ZTxIdSSpendsHash');
    const outputsDigest = sOuts.length
      ? H(
          'ZTxIdSOutputHash',
          H('ZTxIdSOutC__Hash', ...sOuts.flatMap((o) => [o.cmu, o.epk, o.enc.subarray(0, 52)])),
          H('ZTxIdSOutM__Hash', ...sOuts.map((o) => o.enc.subarray(52, 564))),
          H('ZTxIdSOutN__Hash', ...sOuts.flatMap((o) => [o.cv, o.enc.subarray(564), o.out])),
        )
      : H('ZTxIdSOutputHash');
    sapling = H('ZTxIdSaplingHash', spendsDigest, outputsDigest, valueBalance);
  }

  const actions = Array.from({ length: size() }, () => ({ cv: take(32), nf: take(32), rk: take(32), cmx: take(32), epk: take(32), enc: take(580), out: take(80) }));
  let orchard = H('ZTxIdOrchardHash');
  if (actions.length > 0) {
    const flags = take(1);
    const valueBalance = take(8);
    const anchor = take(32);
    take(size()); // proofs
    take(64 * actions.length + 64); // spend auth sigs, binding sig
    orchard = H(
      'ZTxIdOrchardHash',
      H('ZTxIdOrcActCHash', ...actions.flatMap((a) => [a.nf, a.cmx, a.epk, a.enc.subarray(0, 52)])),
      H('ZTxIdOrcActMHash', ...actions.map((a) => a.enc.subarray(52, 564))),
      H('ZTxIdOrcActNHash', ...actions.flatMap((a) => [a.cv, a.rk, a.enc.subarray(564), a.out])),
      flags,
      valueBalance,
      anchor,
    );
  }
  assert.equal(i, bytes.length, 'the whole transaction is read');
  const tx: ZcashTransparentTx = { branchId, lockTime, expiryHeight, inputs, outputs };
  return { header, versionGroupId, tx, transparentEnd, bundles: { sapling, orchard } };
}

