/* ---------------------------------------------------------- published vectors */

test('ZIP-244 vectors: the transparent encoding, the txid digest and the SIGHASH_ALL digest', () => {
  for (const v of ZIP244) {
    const bytes = hexToBytes(v.tx);
    const { header, versionGroupId, tx, transparentEnd, bundles } = parseV5(bytes);
    assert.equal(header, 0x80000005);
    assert.equal(versionGroupId, 0x26a7270a);
    // Header and transparent bundle as ZIP-225 writes them; what follows is the vector's shielded part.
    assert.equal(hex(encodeZcashV5(tx).subarray(0, transparentEnd)), hex(bytes.subarray(0, transparentEnd)));
    // The vectors print both digests as uint256 values, the way nodes print a txid: bytes reversed.
    assert.equal(hex(zcashTxidDigest(tx, bundles).reverse()), v.txid);
    if (v.input === null) continue; // signs no transparent input: its txid alone is pinned
    const spent = v.amounts.map((value, k) => ({ value, script: hexToBytes(v.scriptPubKeys[k]) }));
    assert.equal(hex(zcashSignatureDigest(tx, v.input, spent, bundles).reverse()), v.sighashAll);
  }
});

// Mainnet transaction 4099cfb7…4de5 (block 3 534 930): one P2PKH coin of 1 434 934 zatoshis at
// t1RmRrhY…NqLt spent to t1T3joYU…LqBi, read from a public explorer on 2026-10-29.
const MAINNET_TX =
  '050000800a27a7265b16a5370000000000000000013495373c976f85b03080ca195314bfe1574bec19f092aa195d4680a16d6183a0000000006b483045022100a3f475d5f87e700b12c091cbd18' +
  '2f99c36eff42338d20b911ace727d1f1ea480022060da113ff0249bc5d8226b3af745cb1124b685197e33a0072e1eab813f6d0e3c0121039472a7c591763b333d430b09d15cf6c254cace448d442207ff' +
  '4474eccb2da497ffffffff0126be1500000000001976a91464a3ccce085239af0270ac73119ecaee0405092888ac000000';
const MAINNET_TXID = '4099cfb7cbe8217605b38632802a3dc4942cf4d2bdcb8bb5223067892ad94de5';

test('a Mainnet v5 transaction re-encodes byte for byte, and its signature verifies over this digest', () => {
  const { tx } = parseV5(hexToBytes(MAINNET_TX));
  assert.equal(hex(encodeZcashV5(tx)), MAINNET_TX);
  assert.equal(zcashTxid(tx), MAINNET_TXID);
  assert.equal(tx.branchId, ZCASH_UPGRADES.find((u) => u.name === 'NU6.3')!.branchId);
  const spent = [{ value: 1_434_934n, script: zcashOutputScript('t1RmRrhYbbAka8JZ4APf27rnZ43cHy9NqLt')! }];
  const scriptSig = tx.inputs[0].scriptSig;
  const der = scriptSig.subarray(1, scriptSig[0]);
  const publicKey = scriptSig.subarray(scriptSig[0] + 2);
  assert.equal(scriptSig[scriptSig[0]], 0x01, 'SIGHASH_ALL');
  assert.ok(secp256k1.verify(der, zcashSignatureDigest(tx, 0, spent), publicKey, { prehash: false, format: 'der' }));
  assert.deepEqual(tx.outputs[0].script, zcashOutputScript('t1T3joYURBJ4GystSwNiT5p1e6ECLBNLqBi'));
  // It paid ZIP-317's conventional fee for one input and one output: two grace actions.
  assert.equal(spent[0].value - tx.outputs[0].value, zip317Fee(1, [tx.outputs[0].script]));
});

test('RFC 6979: the deterministic low-S DER signatures the inputs carry', () => {
  const one = new Uint8Array(32);
  one[31] = 1;
  const vectors = [
    ['Satoshi Nakamoto', '934b1ea10a4b3c1757e2b0c017d0b6143ce3c9a7e6a4a49860d7a6ab210ee3d8', '2442ce9d2b916064108014783e923ec36b49743e2ffa1c4496f01a512aafd9e5'],
    [
      'All those moments will be lost in time, like tears in rain. Time to die...',
      '8600dbd41e348fe5c9465ab92d23e3db8b98b873beecd930736488696438cb6b',
      '547fe64427496db33bf66019dacbf0039c04199abb0122918601db38a72cfc21',
    ],
  ];
  for (const [message, r, s] of vectors) {
    const der = secp256k1.sign(sha256(utf8ToBytes(message)), one, { prehash: false, lowS: true, format: 'der' });
    assert.equal(hex(der), `3045022100${r}0220${s}`);
  }
});

