test('ZIP-320 vectors: a t1 address and its TEX form pay the same P2PKH script', () => {
  for (const v of ZIP320) {
    const script = `76a914${v.hash}88ac`;
    assert.equal(base58check.encode(concatBytes(Uint8Array.from(ZEC_P2PKH_VERSION), hexToBytes(v.hash))), v.t);
    assert.equal(bech32m.encode('tex', bech32m.toWords(hexToBytes(v.hash))), v.tex);
    assert.equal(hex(zcashOutputScript(v.t)!), script);
    assert.equal(hex(zcashOutputScript(v.tex)!), script);
    assert.ok(isZcashAddress('zec', v.t, 'mainnet'));
    assert.ok(isZcashAddress('zec', v.tex, 'mainnet'));
  }
});

