test('anything else is no recipient: shielded, test-network, mistyped, another network, test mode', () => {
  const hash = hexToBytes(ZIP320[0].hash);
  const t1 = ZIP320[0].t;
  const refused = [
    // Shielded: the wallet holds no shielded keys (ZIP-316's own Mainnet examples' prefixes).
    'zs1z7rejlpsa98s2rrrfkwmaxu53e4ue0ulcrw0h4x5g8jl04tak0d3mm47vdtahatqrlkngh9sly',
    'u1l8xunezsvhq8fgzfl7404m450nwnd76zshscn6nfys7vyz2ywyh4cc5daaq0c7q2su5lqfh23sp7fcf3h9sp7wnpwqvz0ljqlefxe7zqr0f7lm9ep9eqdtqzg3usxfggue5pdnlgvh4k0gvtqd2nrzag3hjkxlmn5y0u4fd5z6sxq0zxlu8uyw7pqr',
    // Test-network forms of the same key hash: P2PKH `tm…` and TEX `textest1…`.
    base58check.encode(concatBytes(Uint8Array.of(0x1d, 0x25), hash)),
    bech32m.encode('textest', bech32m.toWords(hash)),
    // A TEX string under another prefix, and one under bech32's checksum instead of bech32m's.
    bech32m.encode('tey', bech32m.toWords(hash)),
    bech32.encode('tex', bech32.toWords(hash)),
    // One character changed: the checksum fails.
    `${t1.slice(0, -1)}${t1.endsWith('W') ? 'X' : 'W'}`,
    // Bitcoin's own P2PKH (one version byte, not two).
    '1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa',
    '',
  ];
  for (const address of refused) assert.equal(isZcashAddress('zec', address, 'mainnet'), false, address);
  assert.equal(isZcashAddress('zec', t1, 'testnet'), false);
  assert.equal(isZcashAddress('btc', t1, 'mainnet'), false);
});

