test('ZIP-317: 5000 zatoshis per logical action, two grace actions, 150-byte inputs', () => {
  const p2pkh = zcashOutputScript(ZIP320[0].t)!;
  const p2sh = zcashOutputScript('t3cFfPt1Bcvgez9ZbMBFWeZsskxTkPzGCow')!;
  assert.equal(zip317Fee(1, [p2pkh]), 10_000n);
  assert.equal(zip317Fee(2, [p2pkh, p2pkh]), 10_000n);
  assert.equal(zip317Fee(3, [p2sh, p2pkh]), 15_000n);
  // 75 inputs at 148 bytes are 11 100 bytes: 74 started 150-byte actions.
  assert.equal(zip317Fee(75, [p2pkh, p2pkh]), 370_000n);
  // The dust rule nodes relay by: 3 × (100 × (size + 148) / 1000), integer division.
  assert.equal(zcashDustThreshold(p2pkh), 54n);
  assert.equal(zcashDustThreshold(p2sh), 54n);
});

const branch = (name: string) => ZCASH_UPGRADES.find((u) => u.name === name)!.branchId;
const NU7_HEIGHT = ZCASH_UPGRADES.find((u) => u.name === 'NU7')!.height;

test('the branch id is the table entry the node validates the next block under; expiry before the next upgrade', () => {
  assert.deepEqual(zcashSendWindow(3_500_000, branch('NU6.3'), []), { branchId: branch('NU6.3'), expiryHeight: 3_500_041 });
  // The node validates the next block under another branch: another epoch, or another chain.
  assert.equal(zcashSendWindow(3_500_000, branch('NU6.2'), []), null);
  assert.equal(zcashSendWindow(3_500_000, 0xdeadbeef, []), null);
  // Shortly before NU7 the expiry stops at the block before it...
  assert.deepEqual(zcashSendWindow(NU7_HEIGHT - 11, branch('NU6.3'), []), { branchId: branch('NU6.3'), expiryHeight: NU7_HEIGHT - 1 });
  // ...and too close to it no expiry would be relayed (zcashd's expiring-soon threshold of 3).
  assert.equal(zcashSendWindow(NU7_HEIGHT - 3, branch('NU6.3'), []), null);
  // From NU7: its branch id, and ZIP-218's 120-block delta.
  assert.deepEqual(zcashSendWindow(NU7_HEIGHT, branch('NU7'), []), { branchId: branch('NU7'), expiryHeight: NU7_HEIGHT + 121 });
  // A node not upgraded for NU7 past its height follows a chain this send does not sign for.
  assert.equal(zcashSendWindow(NU7_HEIGHT, branch('NU6.3'), []), null);
  // An upgrade the node lists as active that the table does not have: refused, whatever nextblock says.
  assert.equal(zcashSendWindow(3_500_000, branch('NU6.3'), [{ branchId: 0x12345678, height: 3_499_000 }]), null);
  // One it lists as coming, unknown here: the expiry stops before it.
  assert.deepEqual(zcashSendWindow(3_500_000, branch('NU6.3'), [{ branchId: 0x12345678, height: 3_500_020 }]), {
    branchId: branch('NU6.3'),
    expiryHeight: 3_500_019,
  });
});

/* ------------------------------------------------------------- coin selection */

const coin = (n: number, value: bigint, confirmed = true): ZcashCoin => ({ txid: n.toString(16).padStart(64, '0'), index: n % 3, value, confirmed });
const refusal = async (p: Promise<unknown> | (() => unknown)) => {
  try {
    await (typeof p === 'function' ? p() : p);
    return null;
  } catch (e) {
    return (e as { code?: string }).code ?? (e as Error).message;
  }
};

test('coins: mined before mempool, largest first; change back unless it would be dust', async () => {
  const to = zcashOutputScript(ZIP320[0].t)!;
  const change = zcashOutputScript(ZIP320[1].t)!;
  const coins = [coin(1, 40_000n), coin(2, 500_000n, false), coin(3, 300_000n), coin(4, 90_000n)];
  const plan = planZcashSend(coins, 100_000n, to, change, 100_000n);
  assert.deepEqual(
    plan.inputs.map((c) => c.value),
    [300_000n],
  );
  assert.deepEqual(plan.outputs, [
    { value: 100_000n, script: to },
    { value: 190_000n, script: change },
  ]);
  assert.equal(plan.fee, 10_000n);
  // Two mined coins before the larger mempool one.
  assert.deepEqual(
    planZcashSend(coins, 380_000n, to, change, 100_000n).inputs.map((c) => c.value),
    [300_000n, 90_000n],
  );
  // 53 zatoshis of change is dust: left to the miner.
  const exact = planZcashSend([coin(5, 110_053n)], 100_000n, to, change, 100_000n);
  assert.deepEqual(exact.outputs, [{ value: 100_000n, script: to }]);
  assert.equal(exact.fee, 10_053n);
  // 54 is not.
  assert.equal(planZcashSend([coin(6, 110_054n)], 100_000n, to, change, 100_000n).outputs.length, 2);
  // The fee is capped: one zatoshi under it is refused, and so is the dust a capped fee would absorb.
  assert.equal(await refusal(() => planZcashSend(coins, 100_000n, to, change, 9_999n)), 'fee');
  assert.equal(await refusal(() => planZcashSend([coin(7, 110_053n)], 100_000n, to, change, 10_000n)), 'fee');
  // Twenty 20 000-zatoshi coins pay 300 000 for a 100 000 fee: at the cap it goes, under it does not.
  const small = Array.from({ length: 30 }, (_, k) => coin(10 + k, 20_000n));
  assert.equal(planZcashSend(small, 300_000n, to, change, 100_000n).fee, 100_000n);
  assert.equal(await refusal(() => planZcashSend(small, 300_000n, to, change, 99_999n)), 'fee');
  // Not enough, fee included.
  assert.equal(await refusal(() => planZcashSend(coins, 925_001n, to, change, 100_000n)), 'funds');
  assert.equal(await refusal(() => planZcashSend([], 1_000n, to, change, 100_000n)), 'funds');
});

