test('a send checks the node, spends the largest mined coin, signs ZIP-244 and relays once', async () => {
  const { calls, sent } = services();
  const id = await sendZcash(transfer());
  assert.deepEqual(calls, ['getblockchaininfo', 'getblockhash', 'blockchair', 'sendrawtransaction']);
  assert.equal(sent.length, 1);
  const tx = relayed(sent[0], [300_000n]);
  assert.equal(id, zcashTxid(tx));
  assert.equal(tx.branchId, branch('NU6.3'));
  assert.equal(tx.expiryHeight, TIP + 1 + 40);
  assert.equal(tx.lockTime, 0);
  assert.equal(hex(tx.inputs[0].txid), 'aa'.repeat(32));
  assert.deepEqual(tx.outputs, [
    { value: 100_000n, script: zcashOutputScript(TO)! },
    { value: 190_000n, script: zcashOutputScript(OWNER)! },
  ]);
});

